import java.util.*;
import java.io.*;

public class Main {
    static List<String> process(String[] op, long[] val) {
        // Write your solution here
        // op[i] is "push", "pop", "top" or "size"; val[i] is the pushed value (0 otherwise). Return the output lines in order
        return new ArrayList<>();
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int q = Integer.parseInt(br.readLine().trim());
        String[] op = new String[q];
        long[] val = new long[q];
        for (int i = 0; i < q; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            op[i] = st.nextToken();
            if (op[i].equals("push")) val[i] = Long.parseLong(st.nextToken());
        }
        StringBuilder sb = new StringBuilder();
        for (String line : process(op, val)) sb.append(line).append("\n");
        System.out.print(sb);
    }
}

