def gen(rng):
    def fmt(ops):
        return str(len(ops)) + '\n' + '\n'.join(ops)
    def rand_ops(q, vmax, wpush):
        ops = []
        for _ in range(q):
            r = rng.random()
            if r < wpush:
                ops.append('push %d' % rng.randint(-vmax, vmax))
            else:
                ops.append(rng.choice(['pop', 'pop', 'top', 'size']))
        return ops
    tests = [
        fmt(['pop']), fmt(['top']), fmt(['size']), fmt(['push 7', 'size', 'top', 'pop', 'pop', 'size']),
        fmt(['push 1', 'push 1', 'push 1', 'pop', 'pop', 'pop', 'pop']),
        fmt(['push -1000000000', 'push 1000000000', 'top', 'pop', 'top', 'pop']),
        fmt(['push %d' % x for x in (5, 4, 3, 2, 1)] + ['pop'] * 6),
    ]
    for _ in range(14):
        tests.append(fmt(rand_ops(rng.randint(1, 25), rng.choice([3, 10, 1000]), rng.choice([0.4, 0.6, 0.8]))))
    tests.append(fmt(rand_ops(20000, 10**9, 0.55)))
    big = ['push %d' % rng.randint(-10**9, 10**9) for _ in range(60000)] + ['pop'] * 40000
    tests.append(fmt(big))
    tests.append(fmt(['push %d' % i for i in range(50000, 0, -1)] + ['pop', 'top'] * 25000))
    tests.append(fmt(rand_ops(100000, 100, 0.52)))
    return tests
